<?php

declare(strict_types=1);

namespace Yijing\Core\Data;

/**
 * Ukrainian rendering of {@see HexagramSequenceCatalog} — the 序卦傳 (Xu Gua) rationale for why
 * each hexagram follows the one before it in the King Wen order.
 *
 * PROVENANCE. A machine-assisted translation of James Legge's 1899 English (Appendix VI of
 * 'The Yi King', SBE XVI) — NOT from the original Chinese, NOT a published Ukrainian edition.
 * The English `HexagramSequenceCatalog::ENTRIES` remain the sourced canonical text (SPEC-002);
 * this is a deliberate, user-approved exception limited to the `uk` locale (SPEC-057). Legge's
 * romanised hexagram names are kept as in the English.
 */
final class HexagramSequenceCatalogUk
{
    /** @var array<int, string> King Wen number (3-64) => Ukrainian Xu Gua rationale */
    public const ENTRIES = [
        3 => 'Коли постали небо й земля, то далі народилося все суще. Те, що заповнює простір між небом і землею, — це все суще. Тому за Цянь і Кунь іде Чжунь.',
        4 => 'Чжунь означає заповнення. Чжунь описує речі при їхньому першому народженні. Народившись так, вони неодмінно перебувають у нерозвиненому стані. Тому за Чжунь іде Мен.',
        5 => 'Мен описує нерозвинене — молодь створінь і речей. У такому стані вони потребують живлення. Тому за Мен іде Сюй.',
        6 => 'Сюй описує спосіб, яким постачають їжу й питво. Через їжу й питво неодмінно бувають суперечки. Тому за Сюй іде Сун.',
        7 => 'Сун неодмінно спричиняє повстання множин; і тому за ним іде Ши.',
        8 => 'Ши має значення множин, а між множинами має бути якийсь зв\'язок єднання. Тому за ним іде Бі.',
        9 => 'Бі означає прихильність. Множини в єднанні мають бути піддані певному стримуванню. Тому за Бі іде Сяо Чу.',
        10 => 'Коли речі піддано стримуванню, постають обряди церемоній, і тому за Сяо Чу іде Лі.',
        11 => 'Ступання по належному веде до Тай, що виливається в стан свободи й спокою, і тому за Лі іде Тай.',
        12 => 'Тай означає вільний плин речей. Так не може тривати вічно, і тому за ним іде Пі, що означає замкненість і обмеженість.',
        13 => 'Речі не можуть бути замкнені вічно, і тому за Пі іде Тун Жень.',
        14 => 'Тому, хто плекає єднання з людьми, речі неодмінно почнуть належати, і тому за Тун Жень іде Та Ю.',
        15 => 'Ті, хто має велике, не повинні плекати в собі почуття переповненості, і тому за Та Ю іде Цянь.',
        16 => 'Коли велике володіння поєднане зі скромністю, неодмінно буде втіха й задоволення; і тому за Цянь іде Юй.',
        17 => 'Де пробуджено таку втіху, там той, хто її спричиняє, неодмінно матиме послідовників (Суй).',
        18 => 'Ті, хто йде за іншим, неодмінно мають служби, які треба виконувати, і тому за Суй іде Ґу.',
        19 => 'Ґу означає виконання служб. Той, хто виконує такі служби, може згодом стати великим, і тому за Ґу іде Лінь.',
        20 => 'Лінь означає велике. Велике викликає споглядання, і тому за Лінь іде Ґуань.',
        21 => 'Той, хто притягує споглядання, тоді спричинить єднання інших із собою, і тому за Ґуань іде Ши Хе.',
        22 => 'Ши Хе означає єднання. Але речі не слід єднати безрозсудно чи безладно, і тому за Ши Хе іде Бі.',
        23 => 'Бі означає оздоблення. Коли оздоблення доведено до краю, його поступ добігає кінця; і тому за Бі іде По.',
        24 => 'По означає занепад і повалення. Речі не можна усунути навіки. Коли занепад і повалення завершили свою працю на одному кінці, на другому починається відродження; і тому за По іде Фу.',
        25 => 'Коли відбулося це повернення, немає безрозсудного безладу, і за Фу іде У Ван.',
        26 => 'За свободи від безладу й нещирості, яку означає ця назва, може бути нагромадження чесноти, і за У Ван іде Та Чу.',
        27 => 'Коли відбулося таке нагромадження, за ним настане живлення його; і тому за Та Чу іде І.',
        28 => 'І означає живлення. Без живлення не могло б бути руху, і тому за І іде Та Ґуо.',
        29 => 'Речі не можуть вічно перебувати в стані надзвичайного; і тому за Та Ґуо іде Кань.',
        30 => 'Кань означає падіння в небезпеку. Коли хтось падає в небезпеку, він неодмінно чіпляється за якусь особу чи річ; і тому за Кань іде Лі. Лі означає прихильність, прилягання до чогось.',
        31 => 'Оскільки існують небо й земля, то далі постало все суще. Оскільки існує все суще, далі постали чоловіче й жіноче. Від існування чоловічого й жіночого далі постало подружжя. Від подружжя постали батько й син. Від батька й сина постали правитель і підданий. Від правителя й підданого постали вище й нижче. Коли постало розрізнення вищого й нижчого, далі постали настанови пристойності й праведності.',
        32 => 'Правило для стосунку подружжя таке, що він має бути тривалим. Тому за Сянь іде Хен.',
        33 => 'Хен означає тривалість. Речі не можуть довго перебувати на тому самому місці; і тому за Хен іде Дунь.',
        34 => 'Дунь означає відступ. Речі не можуть бути відсунуті навіки; і за Дунь настає Та Чжуан.',
        35 => 'Речі не можуть лишатися вічно просто в стані сили; і за Та Чжуан настає Цзінь.',
        36 => 'Цзінь означає просування. Але просування неодмінно веде до поранення; і за Цзінь настає Мін І.',
        37 => 'Мін І означає поранення. Той, хто поранений на чужині, повернеться додому; і тому за Мін І іде Цзя Жень.',
        38 => 'Коли належному врядуванню родини настає кінець, постануть непорозуміння й розкол; і тому за Цзя Жень іде Куй.',
        39 => 'Куй означає непорозуміння й розкол; а такий стан неодмінно спричинить труднощі й ускладнення. Тому за Куй іде Цзянь.',
        40 => 'Цзянь означає труднощі; але речі не можуть вічно перебувати в такому стані. Тому за Цзянь іде Цзє.',
        41 => 'Цзє означає послаблення й полегкість. У стані послаблення й полегкості неодмінно бувають утрати; і тому за Цзє іде Сунь.',
        42 => 'Але коли Сунь (зменшення) триває без кінця, неодмінно прийде приріст. Тому за Сунь іде І.',
        43 => 'Коли приріст триває без кінця, неодмінно настане його розсіювання, і тому за І іде Ґуай.',
        44 => 'Ґуай означає розсіювання. Але за розсіюванням має настати нова зустріч. Тому за Ґуай іде Ґоу.',
        45 => 'Ґоу означає таку зустріч. Коли речі зустрічаються разом, тоді утворюється зібрання. Тому за Ґоу іде Цуй.',
        46 => 'Цуй означає бути зібраним. Коли добрих людей зібрано й вони підносяться на найвищі місця, постає те, що ми звемо просуванням угору; і тому за Цуй іде Шен.',
        47 => 'Коли таке просування триває без спину, неодмінно настане утиск; і тому за Шен іде Кунь.',
        48 => 'Коли утиск відчувається на здобутій висоті, неодмінно буде повернення на землю внизу; і тому за Кунь іде Цзін.',
        49 => 'Те, що відбувається за Цзін, потребує зміни, і тому за ним іде Ґе, що означає зміну.',
        50 => 'Для зміни суті речей немає нічого рівного казанові; і тому за Ґе іде Дін.',
        51 => 'Для головування над казаном та всіма іншими посудинами ніхто не рівний старшому синові, і тому за Дін іде Чжень.',
        52 => 'Чжень несе думку про приведення в рух. Але речі не можна тримати в русі вічно. Рух спиняється; і тому за Чжень іде Ґень.',
        53 => 'Ґень дає думку про затримання й спинення. Речі не можна вічно тримати в стані стримування, і тому за Ґень іде Цзянь.',
        54 => 'Цзянь дає думку про поступове просування. З просуванням має бути певна точка, якої досягають, і тому за Цзянь настає Ґуй Мей.',
        55 => 'Коли речі так знаходять належну точку, до якої прийти, вони неодмінно стають великими. Тому за Ґуй Мей настає Фен.',
        56 => 'Фен несе думку про велич. Той, чия велич сягає крайньої можливості, неодмінно втратить своє житло; і тому за Фен настає Люй, що означає мандрівників або чужинців.',
        57 => 'У ньому маємо думку про чужинців, які не мають місця, щоб їх прийняти, і тому за Люй іде Сунь.',
        58 => 'Сунь дає думку про проникання й входження. Хтось входить у здійснення свого наміру, а потім має в ньому втіху; тому за Сунь іде Дуй.',
        59 => 'Дуй означає втіху й задоволення. Ця втіха й задоволення потім починають розсіюватися, і тому за Дуй іде Хуань.',
        60 => 'Хуань означає відділення й розкол. Стан розколу не може тривати вічно, і тому за Хуань іде Цзє.',
        61 => 'Коли Цзє (лад правил) установлено, люди в нього вірять, і тому за ним іде Чжун Фу.',
        62 => 'Коли люди мають віру, яку означає Чжун Фу, вони неодмінно втілять її в діло; і тому за ним настає Сяо Ґуо.',
        63 => 'Той, хто перевершує інших, неодмінно виправить наявне зло, і тому за Сяо Ґуо настає Цзі Цзі.',
        64 => 'Але плин подій не може дійти кінця, і тому за Цзі Цзі настає Вей Цзі, яким гексаграми завершуються.',
    ];
}
